// SPDX-License-Identifier: MIT
plugins { alias(libs.plugins.android.library) }

// C06 pinned NetBare forwarding subset. Only the reviewed IPv4 TCP/UDP proxy
// and NIO tunnel core is vendored; the upstream HTTP/SSL injection, UID
// dumper, sample app and service/base classes are deliberately absent.
// Source revision and local patches are recorded in UPSTREAM.json and
// ../../licenses/netbare/README.md.
android {
    namespace = "com.github.megatronking.netbare"
    compileSdk = 37
    defaultConfig { minSdk = 28 }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}
dependencies {
    // No support library, Guava, BouncyCastle or prebuilt JNI is linked.
    // gradle.lockfile is generated by Main's serialized --write-locks stage.
}
